निम्नलिखित C कोड स्निपेट का आउटपुट क्या होगा?

#include <stdio.h>
int main() {
    int a = 10, b = 20;
    printf("%d", a > b ? a : b);
    return 0;
}

निम्नलिखित C++ कोड का आउटपुट क्या होगा?

#include <iostream>
using namespace std;
int main() {
    int arr[] = {10, 20, 30, 40};
    int *p = arr;
    cout << *(p + 2);
    return 0;
}

निम्नलिखित C++ कोड का आउटपुट क्या होगा?

#include <iostream>
using namespace std;
long factorial(long a) {
    if (a > 1)
        return (a * factorial(a + 1));
    else
        return 1;
}
int main() {
    long num = 3;
    cout << factorial(num);
    return 0;
}
